INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Конституционные полномочия парламента','В проекте указано, что Совет Федерации и Государственная Дума всегда заседают совместно. Какая норма Конституции опровергает это?','["Палаты собираются только на совместные заседания","Палаты Федерального Собрания заседают раздельно","Совет Федерации заседает внутри Государственной Думы","Заседания двух палат проводит исключительно Правительство"]'::jsonb,1,'Конституция Российской Федерации','статья 100','https://www.minjust.gov.ru/ru/documents/8011/','Статья 100 устанавливает раздельные заседания палат; совместные заседания возможны в конституционно предусмотренных случаях.',true),
('Конституционные полномочия парламента','Кто определяет внутренний порядок работы Государственной Думы и Совета Федерации в пределах Конституции?','["Каждая палата принимает собственный регламент","Правительство принимает единый регламент обеих палат","Президент единолично утверждает порядок всех заседаний","Верховный Суд устанавливает правила парламентских голосований"]'::jsonb,0,'Конституция Российской Федерации','статья 101','https://www.minjust.gov.ru/ru/documents/8011/','По статье 101 каждая палата принимает свой регламент и решает вопросы внутреннего распорядка.',true),
('Конституционные полномочия парламента','Кому Конституция относит назначение выборов Президента Российской Федерации?','["Государственной Думе","Правительству Российской Федерации","Счётной палате","Совету Федерации"]'::jsonb,3,'Конституция Российской Федерации','статья 102','https://www.minjust.gov.ru/ru/documents/8011/','Назначение выборов Президента относится к ведению Совета Федерации.',true),
('Конституционные полномочия парламента','Какая палата решает вопрос о возможности использования Вооружённых Сил РФ за пределами территории России?','["Государственная Дума","Счётная палата","Совет Федерации","Конституционный Суд по собственной инициативе"]'::jsonb,2,'Конституция Российской Федерации','статья 102','https://www.minjust.gov.ru/ru/documents/8011/','Статья 102 относит этот вопрос к ведению Совета Федерации.',true),
('Конституционные полномочия парламента','Какая палата назначает по представлению Президента судей Конституционного Суда и Верховного Суда РФ?','["Правительство Российской Федерации","Совет Федерации","Государственная Дума","Центральная избирательная комиссия"]'::jsonb,1,'Конституция Российской Федерации','статья 102','https://www.minjust.gov.ru/ru/documents/8011/','Соответствующее полномочие Совета Федерации закреплено статьёй 102.',true),
('Конституционные полномочия парламента','Какая палата утверждает представленную Президентом кандидатуру Председателя Правительства?','["Государственная Дума","Совет Федерации","Конституционный Суд","Счётная палата"]'::jsonb,0,'Конституция Российской Федерации','статья 103','https://www.minjust.gov.ru/ru/documents/8011/','Статья 103 закрепляет утверждение кандидатуры Председателя Правительства Государственной Думой.',true),
('Конституционные полномочия парламента','Кто вправе выражать недоверие Правительству Российской Федерации в парламентской процедуре?','["Совет Федерации","Общественная палата","Центральная избирательная комиссия","Государственная Дума"]'::jsonb,3,'Конституция Российской Федерации','статья 103','https://www.minjust.gov.ru/ru/documents/8011/','Вопрос о доверии Правительству относится к ведению Государственной Думы.',true),
('Конституционные полномочия парламента','Какая палата осуществляет объявление амнистии?','["Совет Федерации","Правительство","Государственная Дума","Конституционный Суд"]'::jsonb,2,'Конституция Российской Федерации','статья 103','https://www.minjust.gov.ru/ru/documents/8011/','Пункт «е» части 1 статьи 103 относит объявление амнистии к ведению Государственной Думы.',true),
('Конституционные полномочия парламента','Кто назначает и освобождает от должности Уполномоченного по правам человека в Российской Федерации?','["Совет Федерации","Государственная Дума","Председатель Правительства","Генеральный прокурор"]'::jsonb,1,'Конституция Российской Федерации','статья 103','https://www.minjust.gov.ru/ru/documents/8011/','Это полномочие Государственной Думы по статье 103.',true),
('Конституционные полномочия парламента','Может ли законодательный орган субъекта РФ внести законопроект непосредственно в Государственную Думу в порядке законодательной инициативы?','["Да, такое право предусмотрено Конституцией","Нет, только через Правительство","Нет, законопроекты регионов вносит исключительно Президент","Да, но только через Совет Федерации"]'::jsonb,0,'Конституция Российской Федерации','статья 104','https://www.minjust.gov.ru/ru/documents/8011/','Часть 1 статьи 104 наделяет региональные законодательные органы правом законодательной инициативы.',true),
('Конституционные полномочия парламента','В какую палату должны первоначально вноситься законопроекты в рамках федерального законодательного процесса?','["В Совет Федерации","В Конституционный Суд","В Государственный Совет","В Государственную Думу"]'::jsonb,3,'Конституция Российской Федерации','статья 104','https://www.minjust.gov.ru/ru/documents/8011/','Часть 2 статьи 104 требует внесения законопроектов в Государственную Думу.',true),
('Конституционные полномочия парламента','Какое большинство требуется для принятия обычного федерального закона Государственной Думой по общему правилу?','["Большинство лишь от присутствующих на заседании","Две трети от присутствующих независимо от их числа","Большинство голосов от общего числа депутатов","Единогласное одобрение всех фракций"]'::jsonb,2,'Конституция Российской Федерации','статья 105','https://www.minjust.gov.ru/ru/documents/8011/','Часть 2 статьи 105 устанавливает большинство от общего числа депутатов, если Конституция не предусматривает иного.',true),
('Конституционные полномочия парламента','Через какое время после принятия федеральный закон должен быть передан из Государственной Думы в Совет Федерации?','["В течение тридцати дней","В течение пяти дней","Не позднее следующего календарного года","Только после подписания Президентом"]'::jsonb,1,'Конституция Российской Федерации','статья 105','https://www.minjust.gov.ru/ru/documents/8011/','Часть 3 статьи 105 устанавливает пятидневный срок передачи принятого закона.',true),
('Конституционные полномочия парламента','Проект о федеральных налогах и сборах принят Государственной Думой. Обязано ли Совет Федерации его рассмотреть?','["Да, вопросы федеральных налогов и сборов подлежат обязательному рассмотрению","Нет, это относится только к региональным парламентам","Нет, любые налоговые законы рассматриваются лишь по желанию Совета Федерации","Нет, компетенция по налогам принадлежит только Правительству"]'::jsonb,0,'Конституция Российской Федерации','статья 106','https://www.minjust.gov.ru/ru/documents/8011/','Статья 106 требует обязательного рассмотрения Советом Федерации федеральных законов по федеральным налогам и сборам.',true),
('Конституционные полномочия парламента','Какая совокупность большинства необходима для принятия федерального конституционного закона?','["Простое большинство присутствующих в каждой палате","Единогласное голосование только Государственной Думы","2/3 сенаторов и 3/4 депутатов","Не менее 3/4 от общего числа сенаторов и 2/3 от общего числа депутатов Госдумы"]'::jsonb,3,'Конституция Российской Федерации','статья 108','https://www.minjust.gov.ru/ru/documents/8011/','Часть 2 статьи 108 устанавливает квалифицированные большинство в Совете Федерации и Государственной Думе.',true),
('Правительство Российской Федерации','Президент намерен лично председательствовать на заседании Правительства. Возможно ли это по ФКЗ?','["Нет, право принадлежит только Председателю Правительства","Да, только с разрешения Государственной Думы","Да, Президент вправе председательствовать на заседаниях Правительства","Нет, Президент участвует исключительно в заседаниях Совета Федерации"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 1','https://www.consultant.ru/document/cons_doc_LAW_366950/','Часть 4 статьи 1 предусматривает это право Президента.',true),
('Правительство Российской Федерации','Кто утверждает структуру федеральных органов исполнительной власти по предложению Председателя Правительства?','["Государственная Дума","Президент Российской Федерации","Совет Федерации","Председатель Верховного Суда"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 1','https://www.consultant.ru/document/cons_doc_LAW_366950/','Часть 5 статьи 1 предусматривает утверждение структуры Президентом по предложению Председателя Правительства.',true),
('Правительство Российской Федерации','Кто определяет, какими федеральными исполнительными органами руководит Президент, а какими — Правительство?','["Президент Российской Федерации","Только Совет Федерации","Только Счётная палата","Центральная избирательная комиссия"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 1','https://www.consultant.ru/document/cons_doc_LAW_366950/','Статья 1 предусматривает определение этого распределения в структуре федеральных органов исполнительной власти Президентом.',true),
('Правительство Российской Федерации','В проект постановления внесено положение о том, что федеральный министр может одновременно быть сенатором. Соответствует ли это ФКЗ о Правительстве?','["Да, если он состоит в одной политической партии с Президентом","Да, при одобрении председателя Совета Федерации","Да, если он получает только одно денежное содержание","Нет, членам Правительства запрещено быть сенаторами"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_366950/','Часть 3 статьи 4 запрещает совмещение полномочий члена Правительства и сенатора.',true),
('Правительство Российской Федерации','Какой вариант правильно описывает состав Правительства Российской Федерации?','["Президент, сенаторы и главы муниципалитетов","Председатели палат парламента и Генеральный прокурор","Председатель Правительства, его заместители и федеральные министры","Члены Совета Безопасности и председатели региональных парламентов"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 4','https://www.consultant.ru/document/cons_doc_LAW_366950/','Часть 1 статьи 4 перечисляет членов Правительства.',true),
('Правительство Российской Федерации','Какие виды правовых актов издаёт Правительство Российской Федерации на основании и во исполнение законодательства?','["Федеральные конституционные законы и приговоры","Постановления и распоряжения","Указы Президента и решения Конституционного Суда","Регламенты сенаторов и областные уставы"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/','Статья 5 предусматривает постановления и распоряжения Правительства.',true),
('Правительство Российской Федерации','Какая форма акта Правительства преимущественно используется для решений нормативного характера?','["Постановление Правительства","Определение Конституционного Суда","Федеральный закон","Решение муниципального референдума"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 5','https://www.consultant.ru/document/cons_doc_LAW_366950/','Статья 5 различает нормативные постановления и распоряжения по оперативным вопросам.',true),
('Правительство Российской Федерации','Федеральное министерство предлагает, чтобы Правительство координировало реализацию государственной политики. Допускает ли это ФКЗ?','["Нет, политика реализуется исключительно судами","Нет, Правительство работает только над кадровыми назначениями","Да, но только по муниципальным программам","Да, Правительство организует реализацию внутренней и внешней политики"]'::jsonb,3,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 13','https://www.consultant.ru/document/cons_doc_LAW_366950/','Статья 13 предусматривает организацию реализации внутренней и внешней политики Правительством.',true),
('Правительство Российской Федерации','Кто разрабатывает и представляет Государственной Думе проект федерального бюджета?','["Совет Федерации","Конституционный Суд","Правительство Российской Федерации","Центральная избирательная комиссия"]'::jsonb,2,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 19','https://www.consultant.ru/document/cons_doc_LAW_366950/','Статья 19 закрепляет подготовку и внесение федерального бюджета Правительством.',true),
('Правительство Российской Федерации','Может ли Правительство воспользоваться правом законодательной инициативы в Государственной Думе?','["Нет, законопроекты может вносить лишь Президент","Да, это право прямо предусмотрено федеральным законодательством","Нет, только сенаторы обладают таким правом","Да, но исключительно по вопросам иностранных судов"]'::jsonb,1,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 26','https://www.consultant.ru/document/cons_doc_LAW_366950/','Статья 26 регулирует полномочия Правительства в законодательной деятельности.',true),
('Правительство Российской Федерации','Председатель Правительства готовит основные направления деятельности Кабинета. Соответствует ли это его полномочиям?','["Да, он определяет основные направления деятельности Правительства с учётом Конституции и федеральных законов","Нет, эти направления определяет только Совет Федерации","Нет, это полномочие Счётной палаты","Да, но лишь при наличии права законодательной инициативы регионального парламента"]'::jsonb,0,'ФКЗ от 06.11.2020 № 4-ФКЗ «О Правительстве Российской Федерации»','статья 27','https://www.consultant.ru/document/cons_doc_LAW_366950/','Статья 27 определяет полномочия Председателя Правительства в организации его работы.',true),
('Муниципальная публичная власть','Муниципалитет решил исключить представительный орган из структуры, сохранив только администрацию и главу. Возможно ли это по общему правилу?','["Да, при согласии местного казначея","Да, если имеется контрольно-счётный орган","Да, если муниципалитет — городской округ","Нет, представительный орган обязателен"]'::jsonb,3,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 2 статьи 14 делает представительный орган обязательным.',true),
('Муниципальная публичная власть','Какая комбинация органов обязательно должна присутствовать в структуре местного самоуправления?','["Только глава и федеральная налоговая служба","Правительство субъекта, территориальное отделение ЦИК и мэр","Представительный орган, глава муниципального образования и местная администрация","Районный суд, прокуратура и муниципальный казначей"]'::jsonb,2,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 2 статьи 14 содержит перечень обязательных органов.',true),
('Муниципальная публичная власть','Может ли устав муниципального образования предусмотреть иные местные органы с собственными полномочиями?','["Нет, любые дополнительные органы запрещены","Да, при соблюдении Федерального закона № 33-ФЗ","Да, но только приказом федерального министра","Да, только посредством поправки к Конституции РФ"]'::jsonb,1,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 1 статьи 14 допускает иные органы, предусмотренные уставом.',true),
('Муниципальная публичная власть','Какой акт определяет наименования представительного органа, главы муниципалитета и местной администрации с учётом местных традиций?','["Закон соответствующего субъекта РФ","Регламент Государственной Думы","Указ председателя Конституционного Суда","Решение Банка России"]'::jsonb,0,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 5 статьи 14 закрепляет наименования законом субъекта РФ.',true),
('Муниципальная публичная власть','Орган местного самоуправления хочет определить структуру, сроки полномочий и подотчётность без устава. Какому требованию противоречит это решение?','["Все эти вопросы устанавливает исключительно Центральный банк","Структуру любого муниципалитета определяет Гражданский кодекс","Подотчётность устанавливается только избирательными комиссиями","Эти вопросы определяются уставом муниципального образования в соответствии с законом"]'::jsonb,3,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 14','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 3 статьи 14 требует регулирования соответствующих вопросов уставом.',true),
('Муниципальная публичная власть','Вновь избранный представительный орган решил провести первое заседание спустя три месяца после избрания в правомочном составе. Допускается ли такое?','["Да, максимальный срок составляет полгода","Да, если об этом объявлено в социальной сети","Нет, срок первого заседания по уставу не может превышать 30 дней","Да, срок устанавливается только руководителем региона"]'::jsonb,2,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 2 статьи 15 устанавливает максимальный срок 30 дней.',true),
('Муниципальная публичная власть','Из кого состоит представительный орган муниципального образования по статье 15 закона № 33-ФЗ?','["Из представителей всех федеральных министерств","Из депутатов, избранных на муниципальных выборах","Из мировых судей муниципалитета","Из руководителей коммерческих организаций по назначению"]'::jsonb,1,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 15','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 1 статьи 15 определяет депутатский состав представительного органа.',true),
('Муниципальная публичная власть','Кто утверждает отчёт об исполнении местного бюджета?','["Представительный орган муниципального образования","Федеральное казначейство самостоятельно","Только высшее должностное лицо субъекта РФ","Совет Федерации"]'::jsonb,0,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 1 статьи 16 относит утверждение отчёта к исключительной компетенции представительного органа.',true),
('Муниципальная публичная власть','Муниципальная администрация единолично приняла устав муниципального образования. Какое правило нарушено?','["Устав обязан принимать федеральный суд","Устав издаёт Центральный банк","Устав принимают исключительно федеральные министерства","Устав принимается представительным органом в пределах его исключительной компетенции"]'::jsonb,3,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 1 статьи 16 закрепляет принятие устава за представительным органом.',true),
('Муниципальная публичная власть','Может ли представительный орган муниципалитета утверждать правила благоустройства территории?','["Нет, правила утверждает исключительно Госдума","Нет, такие правила устанавливает Центробанк","Да, это предусмотрено законом № 33-ФЗ","Да, только с согласия Конституционного Суда"]'::jsonb,2,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 16','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 1 статьи 16 включает утверждение правил благоустройства в исключительные полномочия.',true),
('Муниципальная публичная власть','Как могут формироваться органы местного самоуправления в рамках статьи 13 закона № 33-ФЗ?','["Исключительно решением регионального арбитражного суда","Гражданами непосредственно на муниципальных выборах либо через избранных депутатов","Только назначением федеральных министров","Только приказом региональной избирательной комиссии"]'::jsonb,1,'ФЗ от 20.03.2025 № 33-ФЗ «Об общих принципах организации местного самоуправления в единой системе публичной власти»','статья 13','https://www.consultant.ru/document/cons_doc_LAW_501319/','Часть 2 статьи 13 устанавливает прямой и опосредованный порядок формирования.',true),
